$ErrorActionPreference="Stop"
$site=Split-Path -Parent $PSScriptRoot
function EH([string]$v){[Net.WebUtility]::HtmlEncode($v)}
function JJ($v){$v|ConvertTo-Json -Depth 10 -Compress}
function SS([string]$v){$v=$v.ToLowerInvariant().Replace("ı","i").Replace("ğ","g").Replace("ü","u").Replace("ş","s").Replace("ö","o").Replace("ç","c");([regex]::Replace($v,"[^a-z0-9]+","-")).Trim("-")}
$cats=@{
tshirt=@("polo-yaka-is-tisortu","İş Tişörtleri","lakost veya penye örme kumaş");sweat=@("kurumsal-is-sweatshirtu","İş Sweatshirtleri","iki veya üç iplik örme kumaş");pantolon=@("is-pantolonu","İş Pantolonları","dayanıklı dokuma kumaş");tulum=@("is-tulumu","İş Tulumları","teknik dokuma kumaş");onluk=@("asci-kiyafeti-is-onlugu","Aşçı Kıyafetleri ve Önlükler","kolay bakımlı dokuma kumaş");montkaban=@("is-montu-kaban","İş Montları","dış yüzey, astar ve dolgu");polar=@("polar-is-montu","Polar İş Montları","göreve uygun polar kumaş");yelek=@("reflektorlu-is-yelegi","İş Yelekleri","softshell, polar veya dolgulu yüzey");softshell=@("softshell-is-montu","Softshell Ürünleri","esnek softshell kumaş")}
$exclude=@("KT-MK-003","KT-MK-004","KT-ON-004","KT-ON-005");$current="";$models=@()
foreach($line in Get-Content (Join-Path $site "products.js") -Encoding UTF8){$id=[regex]::Match($line,'^\s+id:\s*"([^"]+)"');if($id.Success){$current=$id.Groups[1].Value;continue};if(!$cats.ContainsKey($current)){continue};$m=[regex]::Match($line,'img:\s*"([^"]+)".*code:\s*"(KT-[^"]+)".*name:\s*"([^"]+)".*tags:\s*"([^"]+)"');if($m.Success-and$m.Groups[2].Value-notin$exclude){$description=[regex]::Match($line,'description:\s*"([^"]+)"').Groups[1].Value;$models+=[pscustomobject]@{cat=$current;img=$m.Groups[1].Value;code=$m.Groups[2].Value;name=$m.Groups[3].Value;tags=$m.Groups[4].Value;description=$description}}}
if($models.Count-ne 118){throw "118 model bekleniyordu: $($models.Count)"}
$modelLinks=@($models|ForEach-Object{[pscustomobject]@{slug="urun/$(SS "$($_.code)-$($_.name)")";name=$_.name;code=$_.code;cat=$_.cat}})
$utf8=New-Object Text.UTF8Encoding($false);$links=@()
foreach($m in $models){$c=$cats[$m.cat];$slug="urun/$(SS "$($m.code)-$($m.name)")";$url="https://kardeslertekstil.com.tr/$slug/";$webp=[regex]::Replace($m.img,'\.(png|jpe?g)$','.webp','IgnoreCase');$image="https://kardeslertekstil.com.tr/assets/products/gallery/$($m.cat)/$webp";$desc=if($m.description){$m.description}else{"$($m.name) ($($m.code)): $($m.tags). Minimum 50 adet özel üretim, kurumsal renk, baskı ve nakış seçenekleri."};$items=@($m.tags-split'\s*\|\s*');$lis=($items|ForEach-Object{"<li>$(EH $_)</li>"})-join""
$categorySlug=$c[0];$categoryLabel='Kategori'
if($m.cat-eq'yelek'-and($m.name-match'Yazlık')){$categorySlug='yazlik-isci-yelegi';$categoryLabel='Yazlık İşçi Yelekleri'}
elseif($m.cat-eq'yelek'-and($m.name-match'Silikon|Kışlık')){$categorySlug='silikon-elyaf-dolgulu-is-yelegi';$categoryLabel='Kışlık İş Yelekleri'}
elseif($m.cat-eq'polar'-and($m.name-match'Kapüşonlu')){$categorySlug='kapusonlu-polar-is-montu';$categoryLabel='Kapüşonlu Polarlar'}
elseif($m.cat-eq'montkaban'-and($m.name-match'Kaban')){$categorySlug='uzun-is-kabani';$categoryLabel='Uzun İş Kabanları'}
elseif($m.cat-eq'tulum'-and($m.name-match'Bahçıvan')){$categorySlug='bahcivan-is-tulumu';$categoryLabel='Bahçıvan Tulumları'}
elseif($m.cat-eq'softshell'-and($m.name-match'Yelek')){$categorySlug='softshell-is-yelegi';$categoryLabel='Softshell Yelekler'}
elseif($m.cat-eq'softshell'-and($m.name-match'Pantolon')){$categorySlug='softshell-is-pantolonu';$categoryLabel='Softshell Pantolonlar'}
$faq=@(@{q="Minimum sipariş kaç adettir?";a="Bu modelde özel üretim minimum siparişi 50 adettir."},@{q="Logo uygulanabilir mi?";a="Kumaşa göre nakış, DTF, transfer veya serigrafi uygulanabilir."},@{q="Farklı renk üretilebilir mi?";a="Kumaş ve aksesuar uygunluğuna göre kurumsal renk planlanabilir."},@{q="Numune hazırlanabilir mi?";a="Proje kapsamına göre seri üretim öncesinde numune hazırlanabilir."},@{q="Beden dağılımı nasıl belirlenir?";a="Çalışan listesi ve numune kontrolüyle beden dağılımı yazılı onaya alınır."},@{q="Teklif için ne gerekir?";a="Adet, beden, renk, logo, teslimat şehri ve hedef tarih paylaşılmalıdır."});$faqHtml=($faq|ForEach-Object{"<details><summary>$(EH $_.q)</summary><p>$(EH $_.a)</p></details>"})-join""
$related=@($modelLinks|Where-Object{$_.cat-eq$m.cat-and$_.code-ne$m.code}|Select-Object -First 3)
$relatedCards=($related|ForEach-Object{"<a class=`"local-product-card`" href=`"../../$($_.slug)/`"><h3>$(EH $_.name)</h3><p>$($_.code) kodlu kurumsal üretim modelini inceleyin.</p><strong>Ürün detayına gidin →</strong></a>"})-join""
$product=@{"@context"="https://schema.org";"@type"="Product";"@id"="$url#product";name=$m.name;sku=$m.code;description=$desc;url=$url;image=@($image);category=$c[1];brand=@{"@type"="Brand";name="Kardeşler Tekstil"};manufacturer=@{"@id"="https://kardeslertekstil.com.tr/#organization"};additionalProperty=@($items|ForEach-Object{@{"@type"="PropertyValue";name="Özellik";value=$_}})}
$bread=@{"@context"="https://schema.org";"@type"="BreadcrumbList";itemListElement=@(@{"@type"="ListItem";position=1;name="Ana Sayfa";item="https://kardeslertekstil.com.tr/"},@{"@type"="ListItem";position=2;name="Ürünlerimiz";item="https://kardeslertekstil.com.tr/urunlerimiz"},@{"@type"="ListItem";position=3;name=$m.name;item=$url})};$faqSchema=@{"@context"="https://schema.org";"@type"="FAQPage";mainEntity=@($faq|ForEach-Object{@{"@type"="Question";name=$_.q;acceptedAnswer=@{"@type"="Answer";text=$_.a}}})}
$html=@"
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>$(EH $m.name) | $($m.code)</title><meta name="description" content="$(EH $desc)"><link rel="canonical" href="$url"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="stylesheet" href="../../styles.css?v=20260803-5"><meta property="og:type" content="product"><meta property="og:title" content="$(EH $m.name)"><meta property="og:description" content="$(EH $desc)"><meta property="og:url" content="$url"><meta property="og:image" content="$image"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="$(EH $m.name)"><meta name="twitter:description" content="$(EH $desc)"><meta name="twitter:image" content="$image"><script type="application/ld+json">$(JJ $product)</script><script type="application/ld+json">$(JJ $bread)</script><script type="application/ld+json">$(JJ $faqSchema)</script><link rel="icon" type="image/png" sizes="48x48" href="/favicon-48x48.png?v=13"><link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png?v=13"><link rel="shortcut icon" href="/favicon.ico?v=13"><script src="/site.js?v=20260804-2" defer></script></head><body class="local-page product-model-page"><header class="site-header"><div class="container"><a class="brand" href="../../"><img decoding="async" width="1424" height="940" src="../../assets/logo-kit-badge.webp" alt="Kardeşler Tekstil"></a><nav class="nav"><a href="../../">Ana Sayfa</a><a href="../../urunlerimiz">Ürünlerimiz</a><a href="../../hakkimizda">Hakkımızda</a><a href="../../iletisim">İletişim</a></nav><a class="btn btn-accent" href="https://wa.me/902163961988">Teklif Al</a></div></header><main><section class="page-head product-model-hero"><div class="container product-model-hero-grid"><div><div class="eyebrow eyebrow-accent">$($m.code) · $(EH $c[1])</div><h1>$(EH $m.name)</h1><p>$(EH $desc)</p><div class="cta-row"><a class="btn btn-whatsapp" href="https://wa.me/902163961988?text=$([Uri]::EscapeDataString("$($m.code) için teklif almak istiyorum"))">WhatsApp</a><a class="btn btn-quote-form" href="../../iletisim?urun=$([Uri]::EscapeDataString($m.name))#teklif-formu">Teklif İsteyin</a></div></div><figure><img decoding="async" fetchpriority="high" width="800" height="800" src="../../assets/products/gallery/$($m.cat)/$webp" alt="$(EH "$($m.name) ürün görseli")"></figure></div></section><section class="local-section"><div class="container product-seo-copy"><div><h2>$(EH $m.name) üretim ayrıntıları</h2><p>$(EH "$($m.name), kurumsal ekiplerde görev işlevi ve düzenli görünümü bir araya getirmek üzere planlanan $($c[1].ToLowerInvariant()) modellerindendir. $($m.tags) özellikleri modelin temel çerçevesini oluşturur.")</p><p>$(EH "Malzeme seçimi $($c[2]) üzerinden; çalışma ortamı, vardiya süresi, hareket ve bakım düzeni dikkate alınarak yapılır. Dikiş, cep ve kapama noktaları numunede kontrol edilir.")</p><p>Logo ölçüsü ve konumu kumaş yüzeyiyle birlikte değerlendirilir. Onaylanan nakış veya baskı uygulaması model koduna bağlanarak tekrar sipariş standardı korunur.</p><p>Adet, beden dağılımı, renk, teslimat noktası ve hedef tarih yazılı paylaşıldığında kumaş ve üretim planı netleştirilir. Seri üretim yalnız onaylanan kapsam üzerinden ilerler.</p></div><aside class="local-service-note"><strong>$($m.code)</strong><p>$(EH $m.tags)</p><span>Minimum 50 adet · Özel üretim</span></aside></div></section><section class="local-section local-section-muted"><div class="container"><h2>Model özellikleri</h2><ul class="product-model-features">$lis</ul></div></section><section class="local-section"><div class="container local-faq"><h2>Sık sorulan sorular</h2>$faqHtml</div></section><section class="local-final-cta"><div class="container"><div><h2>$($m.code) için teklif alın.</h2><p>Ürün, adet, beden ve logo bilgilerinizi paylaşın.</p></div><div class="local-cta-actions"><a class="btn btn-whatsapp" href="https://wa.me/902163961988">WhatsApp</a><a class="btn btn-quote-form" href="../../iletisim?urun=$([Uri]::EscapeDataString($m.name))#teklif-formu">Teklif Formu</a><a class="btn btn-secondary-dark" href="../../$categorySlug/">$(EH $categoryLabel)</a></div></div></section></main><footer class="site-footer"><div class="container"><p>© 2026 Kardeşler Tekstil</p></div></footer></body></html>
"@
$relatedBlock="<section class=`"local-section`"><div class=`"container`"><h2>Benzer ürünler</h2><div class=`"local-product-grid`">$relatedCards</div></div></section>"
$html=$html.Replace('<section class="local-section"><div class="container local-faq">',"$relatedBlock<section class=`"local-section`"><div class=`"container local-faq`">")
$dir=Join-Path $site $slug;New-Item -ItemType Directory -Force -Path $dir|Out-Null;[IO.File]::WriteAllText((Join-Path $dir "index.html"),$html,$utf8);$links+=[pscustomobject]@{slug=$slug;name=$m.name;code=$m.code}}
$catalogPath=Join-Path $site "urunlerimiz.html";$catalog=[IO.File]::ReadAllText($catalogPath,[Text.Encoding]::UTF8);$cards=($links|ForEach-Object{"<a class=""home-sector-card"" href=""$($_.slug)/""><span class=""eyebrow eyebrow-accent"">$($_.code)</span><h3>$(EH $_.name)</h3><p>Model ayrıntılarını inceleyin.</p></a>"})-join"";$block="<section class=""catalog-model-pages""><div class=""section-head""><div><div class=""eyebrow eyebrow-accent"">DETAYLI ÜRÜNLER</div><h2>Öne Çıkan Modeller</h2></div></div><div class=""home-sector-grid"">$cards</div></section>";if($catalog-match'<section class="catalog-model-pages"'){$catalog=[regex]::Replace($catalog,'(?is)<section class="catalog-model-pages".*?</section>',$block)}else{$catalog=$catalog.Replace('<section class="catalog-content-block"',"$block<section class=""catalog-content-block""")};[IO.File]::WriteAllText($catalogPath,$catalog,$utf8)
$mapPath=Join-Path $site "sitemap.xml";$map=[IO.File]::ReadAllText($mapPath,[Text.Encoding]::UTF8);$map=[regex]::Replace($map,'(?is)\s*<!-- MODEL-PAGES-START -->.*?<!-- MODEL-PAGES-END -->','');$urls=($links|ForEach-Object{"  <url><loc>https://kardeslertekstil.com.tr/$($_.slug)/</loc><lastmod>2026-08-02</lastmod></url>"})-join[Environment]::NewLine;$map=$map.Replace('</urlset>',"  <!-- MODEL-PAGES-START -->$([Environment]::NewLine)$urls$([Environment]::NewLine)  <!-- MODEL-PAGES-END -->$([Environment]::NewLine)</urlset>");[IO.File]::WriteAllText($mapPath,$map,$utf8)
& (Join-Path $PSScriptRoot 'normalize_entity_schema.ps1')
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
Write-Output "Generated $($models.Count) model pages."
